package com.franco.desco.application.fieldtrip.service;
import com.franco.desco.application.fieldtrip.*;import com.franco.desco.application.fieldtrip.port.in.FieldTripUseCase;import com.franco.desco.application.fieldtrip.port.out.FieldTripPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.fieldtrip.FieldTripModels;
public final class FieldTripApplicationService implements FieldTripUseCase{private final FieldTripPersistencePort p;public FieldTripApplicationService(FieldTripPersistencePort p){this.p=p;}
 public AppResult<PageResult<FieldTripModels.Summary>> list(FieldTripCommands.ListTrips c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"SALIDAS_LISTADAS","SALIDAS_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<FieldTripModels.Detail> get(FieldTripCommands.GetTrip c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"SALIDA_CONSULTADA","SALIDA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long> program(FieldTripCommands.Program c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.program(c,i,m),"SALIDA_PROGRAMADA","SALIDA_NO_PROGRAMADA");}public AppResult<Void> update(FieldTripCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"SALIDA_ACTUALIZADA","SALIDA_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void> cancel(FieldTripCommands.Cancel c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.cancel(c,i,m),"SALIDA_CANCELADA","SALIDA_NO_CANCELADA",AppStatus.BAD_REQUEST);}public AppResult<Void> finish(FieldTripCommands.Finish c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.finish(c,i,m),"SALIDA_FINALIZADA","SALIDA_NO_FINALIZADA",AppStatus.BAD_REQUEST);}}
